<template><section class="workspace-page space-y-8"><PageHeader title="Media library" description="Reuse approved images, videos, documents, and bounded GLB models across branded surfaces and business records."><template #actions><Button type="button" @click="showForm = !showForm"><Upload class="h-4 w-4" /> Upload asset</Button></template></PageHeader><form v-if="showForm" class="grid gap-4 border-y bg-secondary/35 p-5 lg:grid-cols-[1fr_1fr_1fr_auto] lg:items-end" @submit.prevent="upload"><label class="field-label">Title<Input v-model.trim="form.title" class="mt-1" required /></label><label class="field-label">Type<NativeSelect v-model="form.asset_type" class="mt-1"><option value="image">Image</option><option value="video">Video</option><option value="document">Document</option><option value="model">3D model</option></NativeSelect></label><label class="field-label">File<Input class="mt-1" type="file" :accept="fileAccept" required @change="form.file = $event.target.files?.[0]" /></label><Button :disabled="saving">{{ saving ? 'Uploading…' : 'Upload' }}</Button></form><StatePanel v-if="loading" kind="loading" title="Loading assets" message="Retrieving the business media library." /><StatePanel v-else-if="!assets.length" title="No reusable assets yet" message="Upload a brand image, MP4/WebM video, document, or approved GLB model. Public responses expose only assets referenced by saved content." /><div v-else class="grid gap-px border bg-border sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4"><article v-for="asset in assets" :key="asset.public_id" class="bg-card p-4"><div class="flex aspect-[4/3] items-center justify-center overflow-hidden bg-muted"><img v-if="asset.asset_type === 'image'" :src="asset.file_url" :alt="asset.alt_text || asset.title" class="h-full w-full object-cover"><video v-else-if="asset.asset_type === 'video'" :src="asset.file_url" class="h-full w-full object-cover" muted preload="metadata" /><FileBox v-else class="h-10 w-10 text-muted-foreground" /></div><p class="mt-3 font-bold">{{ asset.title }}</p><p class="mt-1 text-xs text-muted-foreground">{{ asset.asset_type }} · {{ size(asset.size_bytes) }}</p></article></div></section></template>
<script setup>import { FileBox, Upload } from 'lucide-vue-next'; const business = useBusinessStore(); const { apiFetch } = useApiClient(); const assets = ref([]); const loading = ref(true); const showForm = ref(false); const saving = ref(false); const form = reactive({ title: '', asset_type: 'image', file: null }); const fileAccept = computed(() => ({ image: 'image/jpeg,image/png,image/webp,image/avif', video: 'video/mp4,video/webm', document: 'application/pdf', model: '.glb,model/gltf-binary' }[form.asset_type])); onMounted(async () => { if (!business.activeBusiness) await business.loadBusinesses(); await load() }); async function load() { loading.value = true; const response = await apiFetch(`businesses/${business.activeBusiness.public_id}/assets/`); assets.value = response.results || []; loading.value = false } async function upload() { saving.value = true; try { const body = new FormData(); body.append('title', form.title); body.append('asset_type', form.asset_type); body.append('file', form.file); const asset = await apiFetch(`businesses/${business.activeBusiness.public_id}/assets/`, { method: 'POST', body }); assets.value.unshift(asset); Object.assign(form, { title: '', asset_type: 'image', file: null }); showForm.value = false } finally { saving.value = false } } function size(bytes) { if (bytes < 1024 * 1024) return `${Math.ceil(bytes / 1024)} KB`; return `${(bytes / 1024 / 1024).toFixed(1)} MB` }</script>
